class Calc {
    int mix(int a, int b) { return a + b; }
    int mix(double a, int b) { return (int)a - b; }
    String mix(String a, int b) { return a + b; }

    public static void main(String[] args) {
        Calc c = new Calc();
        System.out.print(c.mix(3, 2));
        System.out.print(",");
        System.out.print(c.mix(3.0, 2));
        System.out.print(",");
        System.out.print(c.mix("A", 2));
    }
}

class Parent {
    String f() { return "P"; }
}
class Child extends Parent {
    @Override
    String f() { return "C"; }
}
public class Main {
    public static void main(String[] args) {
        Parent a = new Child();
        Child b = new Child();
        System.out.print(a.f());
        System.out.print(b.f());
    }
}

interface Pay {
    String mode();
}
class Card implements Pay {
    public String mode() { return "CARD"; }
}
class Wire implements Pay {
    public String mode() { return "WIRE"; }
}
public class Main {
    static void printMode(Pay p) {
        System.out.print(p.mode());
    }
    public static void main(String[] args) {
        Pay p = new Wire();
        printMode(p);
        p = new Card();
        printMode(p);
    }
}

public class Main {
    static int f() {
        try {
            System.out.print("T");
            return 1;
        } catch (Exception e) {
            System.out.print("C");
            return 2;
        } finally {
            System.out.print("F");
        }
    }
    public static void main(String[] args) {
        System.out.print(f());
    }
}

def f(n):
    if n <= 1:
        return 1
    return f(n-1) + n

