#include <stdio.h>
#include <string.h>

typedef struct {
    char *name;
    int score;
} Account;

int main() {
    char buf[] = "KIM";
    Account a = { buf, 80 };
    Account b = a;
    b.name[0] = 'L';
    b.score = 90;
    printf("%s %d / %s %d", a.name, a.score, b.name, b.score);
    return 0;
}
